def _directory(workspace, key):
    return workspace.root / "water-context" / identifier(key)


def _read_record(workspace, key):
    path = _directory(workspace, key) / "analysis.json"
    record = read_json(path)
    if record.get("schema") != SCHEMA or record.get("id") != key:
        raise ValueError("Select an original Water and Habitat Context analysis")
    if digest(record["identity"]) != key:
        raise ValueError("The retained context source selection changed")
    return record


def get_saved(workspace, analysis_id):
    """Read one saved manifest without rescanning or rehashing original GIS sources."""
    workspace = _workspace(workspace)
    return _read_record(workspace, identifier(analysis_id))


def list_saved(workspace):
    """Read saved manifests only; expensive computations never run during refresh."""
    workspace = _workspace(workspace)
    directory = workspace.root / "water-context"
    result = []
    if not directory.exists():
        return result
    for path in sorted(directory.glob("*/analysis.json")):
        record = _read_record(workspace, path.parent.name)
        result.append({key: record.get(key) for key in
                       ("schema", "id", "title", "state", "created_at", "completed_at",
                        "selection", "selection_id", "summary", "units", "files", "error")})
    return sorted(result, key=lambda value: (value.get("created_at") or "", value["id"]),
                  reverse=True)


def preview(workspace, analysis_id):
    workspace = _workspace(workspace)
    record = _read_record(workspace, identifier(analysis_id))
    if record["state"] != "complete":
        return {"id": record["id"], "status": record["state"],
                "geojson": {"type": "FeatureCollection", "features": []},
                "feature_count": 0, "shown_features": 0, "truncated": False}
    path = verify_file(_directory(workspace, record["id"]), record["files"]["preview"])
    return read_json(path)


def verify_all(workspace):
    """Explicit full verification of saved exports and source selections."""
    workspace = _workspace(workspace)
    checked, errors = [], []
    directory = workspace.root / "water-context"
    for path in sorted(directory.glob("*/analysis.json")) if directory.exists() else []:
        try:
            record = _read_record(workspace, path.parent.name)
            selected = workspace._get("water-context-selections", record["selection_id"])
            actual = {key: value for key, value in selected.items() if key not in ("id", "schema")}
            if actual != record["selection"]:
                raise ValueError("Saved selection differs from the original Workspace record")
            if record["state"] != "complete":
                errors.append({"id": record["id"], "state": record["state"],
                               "error": "Analysis exports are not complete"})
                continue
            for item in record["files"].values():
                verify_file(path.parent, item)
            seen = set()
            for source in record["sources"]:
                key = (source["collection_id"], source["source_id"])
                if key in seen:
                    continue
                seen.add(key)
                _, entry = workspace.source_file(*key)
                if entry["body"]["sha256"] != source["sha256"]:
                    raise ValueError("Saved source identity differs from its retained edition")
            checked.append({"id": record["id"], "files": len(record["files"]),
                            "source_entries": len(seen), "status": "verified"})
        except Exception as error:
            errors.append({"id": path.parent.name, "error": type(error).__name__ + ": " + str(error)})
    return {"schema": "upstate.water-context-verification/v1", "checked_at": now(),
            "ok": not errors, "analyses_checked": len(checked), "analyses": checked,
            "errors": errors}


class _BuildSourceCache:
    """Reuse one verified native source view within one explicit analysis build."""
    def __init__(self, workspace):
        self.workspace, self.views = workspace, {}
        self.root = workspace.root

    def _get(self, kind, key):
        return self.workspace._get(kind, key)

    def source_file(self, collection_id, source_id):
        key = (collection_id, source_id)
        if key not in self.views:
            self.views[key] = self.workspace.source_file(collection_id, source_id)
        return self.views[key]


def build(workspace, spec):
    """Create or reopen a complete deterministic context analysis.

    GIS imports, source verification and geometry work occur only in this explicit
    operation. Source inputs and saved choices remain immutable; failed derivations
    can be resumed by calling build with the same selection.
    """
    from pyproj import CRS, Transformer
    workspace = _workspace(workspace)
    spec = _normalise(spec)
    crs = CRS.from_user_input(spec["measurement_crs"])
    if (not crs.is_projected or len(crs.axis_info) < 2 or
            any(not math.isclose(axis.unit_conversion_factor, 1.0, rel_tol=0, abs_tol=1e-12)
                for axis in crs.axis_info[:2])):
        raise ValueError("Choose a projected measurement CRS with horizontal metre units")
    spec["measurement_crs"] = crs.to_string()
    if "wetlands" in spec["overlays"] and "mapping_status" not in spec["overlays"]:
        entry, _ = _entry(workspace, spec["overlays"]["wetlands"])
        if entry.get("kind") == "raster" and _metadata(entry, "mapping_status_path"):
            spec["overlays"]["mapping_status"] = {
                **spec["overlays"]["wetlands"], "component": "mapping_status"}
    selected = workspace._save("water-context-selections", spec)
    sources = [_source_record(workspace, spec["boundary"], "selection")]
    sources.extend(_source_record(workspace, ref, category)
                   for category, ref in sorted(spec["overlays"].items()))
    sources.extend(_source_record(workspace, ref, ref["kind"]) for ref in spec["relations"])
    identity = {"schema": SCHEMA, "method": METHOD, "selection": spec,
                "selection_id": selected["id"], "sources": sources}
    key = digest(identity)
    directory = _directory(workspace, key)
    directory.mkdir(parents=True, exist_ok=True)
    state_path = directory / "analysis.json"
    with held(directory / ".build.lock", blocking=False):
        if state_path.exists():
            record = _read_record(workspace, key)
            if record["state"] == "complete":
                for item in record["files"].values():
                    verify_file(directory, item)
                return record
        else:
            record = {"schema": SCHEMA, "id": key, "title": spec["title"],
                      "created_at": now(), "state": "building", "selection": spec,
                      "selection_id": selected["id"], "identity": identity,
                      "sources": sources, "units": UNITS, "summary": {}, "files": {},
                      "author": "TokenJunkieLabs"}
        record.update(state="building", error=None, updated_at=now())
        atomic_json(state_path, record)
        pending = Path(tempfile.mkdtemp(prefix=".water-context-", dir=directory))
        try:
            access, corrections = _BuildSourceCache(workspace), []
            boundary_rows = _rows(access, spec["boundary"], crs, "boundary", corrections)
            boundary = _union(boundary_rows)
            if boundary.is_empty or not boundary.is_valid or boundary.area <= 0:
                raise ValueError("Select a nonempty valid polygon reporting boundary")
            if not all(math.isfinite(x) for x in boundary.bounds):
                raise ValueError("The selected boundary has nonfinite projected coordinates")
            layers, supplied = {}, {}
            for category, ref in spec["overlays"].items():
                layers[category] = _rows(access, ref, crs, category, corrections, clip=boundary)
                supplied[category] = _source_record(workspace, ref, category)
            relation_rows = [{**row, "relation_kind": "selection"} for row in boundary_rows]
            for ref in spec["relations"]:
                rows = _rows(access, ref, crs, "boundary", corrections, clip=boundary)
                relation_rows.extend({**row, "relation_kind": ref["kind"]} for row in rows)
            unique_relations = {}
            for row in relation_rows:
                native_key = (row["relation_kind"], row["collection_id"], row["source_id"], row["id"])
                if native_key in unique_relations:
                    if not row["geometry"].equals(unique_relations[native_key]["geometry"]):
                        raise ValueError("Repeated boundary identity carries different selected geometry")
                else:
                    unique_relations[native_key] = row
            relation_rows = list(unique_relations.values())
            summary = _summaries(boundary, layers, supplied, crs)
            summary["selection_feature_count"] = _count(boundary_rows)
            summary["relationship_boundary_count"] = len(relation_rows)
            indices = {category: _SpatialIndex(rows) for category, rows in layers.items()}
            boundary_summaries = []
            for row in relation_rows:
                local_layers = {
                    category: _clipped_rows(index.query(row["geometry"]), row["geometry"], category)
                    for category, index in indices.items()}
                boundary_summaries.append({
                    "kind": row["relation_kind"], "collection_id": row["collection_id"],
                    "source_id": row["source_id"], "feature_id": row["id"], "label": row["label"],
                    "source_boundary_area_ha": row["source_area_ha"],
                    "selected_overlap_area_ha": float(row["geometry"].area) / 10000.0,
                    "selection_share_pct": 100.0 * float(row["geometry"].area) / boundary.area,
                    "source_boundary_share_pct": 100.0 * float(row["geometry"].area) / (row["source_area_ha"] * 10000.0),
                    "inventory_denominator": "Selected overlap with this native boundary",
                    "summary": _summaries(row["geometry"], local_layers, supplied, crs)})
            all_rows = [("selection", row) for row in boundary_rows]
            all_rows.extend((row["relation_kind"], row) for row in relation_rows
                            if row["relation_kind"] != "selection")
            all_rows.extend((category, row) for category, rows in layers.items() for row in rows)
            project = Transformer.from_crs(crs, "EPSG:4326", always_xy=True)
            atomic_json(pending / "selection.json", {**spec, "selection_id": selected["id"]})
            atomic_json(pending / "summary.json", {"schema": SCHEMA, "id": key,
                                                   "summary": summary, "units": UNITS})
            atomic_json(pending / "sources.json", {"sources": sources})
            atomic_json(pending / "geometry-corrections.json", {"corrections": corrections})
            atomic_json(pending / "boundary-summaries.json", {"boundaries": boundary_summaries})
            atomic_json(pending / "preview.json", _preview_value(key, all_rows, project))
            _write_geojson(pending / "features.geojson", all_rows, project, {
                "schema": SCHEMA, "analysis_id": key, "measurement_crs": crs.to_string(),
                "coordinate_reference": "WGS84 longitude, latitude; horizontal XY",
                "original_sources": "sources.json",
                "area_method": "Projected polygon intersections and geometric unions",
                "length_method": "WGS84 ellipsoidal geodesic length of clipped line unions"})
            summary_fields = ["context_role", "label", "status", "feature_count", "footprint_count",
                              "area_ha", "length_km", "area_pct", "coverage_pct", "covered_area_ha",
                              "unmapped_area_ha", "digital_area_ha", "provider_no_data_area_ha",
                              "conflicting_area_ha", "unknown_area_ha", "mapped_occurrence_area_ha",
                              "mapped_no_selected_occurrence_area_ha",
                              "mapped_no_published_occurrence_area_ha",
                              "published_occurrence_outside_mapped_area_ha"]
            _write_csv(pending / "summary.csv", ["boundary_area_ha"] + summary_fields,
                       ({"boundary_area_ha": summary["boundary_area_ha"], "context_role": category,
                         **summary[category]} for category in CATEGORIES))
            feature_fields = ["context_role", "collection_id", "source_id", "feature_id",
                              "identity_kind", "label", "source_area_ha", "area_ha", "length_km", "wetland_type",
                              "ftype", "gap_status", "stream_order", "nhdplusid",
                              "permanent_identifier", "properties_json"]
            _write_csv(pending / "features.csv", feature_fields, _feature_table(all_rows, crs))
            relationship_fields = ["context_role", "collection_id", "source_id", "feature_id",
                                   "identity_kind", "boundary_kind", "boundary_collection_id",
                                   "boundary_source_id", "boundary_feature_id", "boundary_label",
                                   "relationship", "area_ha", "length_km"]
            _write_csv(pending / "relationships.csv", relationship_fields,
                       _relationships(all_rows, relation_rows, crs))
            _write_csv(pending / "boundary-summaries.csv",
                       ["boundary_kind", "collection_id", "source_id", "feature_id",
                        "boundary_label", "boundary_area_ha", "source_boundary_area_ha",
                        "selected_overlap_area_ha", "selection_share_pct",
                        "source_boundary_share_pct", "inventory_denominator"] + summary_fields,
                       ({"boundary_kind": row["kind"], "collection_id": row["collection_id"],
                         "source_id": row["source_id"], "feature_id": row["feature_id"],
                         "boundary_label": row["label"],
                         "boundary_area_ha": row["summary"]["boundary_area_ha"],
                         "source_boundary_area_ha": row["source_boundary_area_ha"],
                         "selected_overlap_area_ha": row["selected_overlap_area_ha"],
                         "selection_share_pct": row["selection_share_pct"],
                         "source_boundary_share_pct": row["source_boundary_share_pct"],
                         "inventory_denominator": row["inventory_denominator"],
                         "context_role": category, **row["summary"][category]}
                        for row in boundary_summaries for category in CATEGORIES))
            record.update(summary=summary, geometry_corrections=len(corrections), notes=[
                "Headline metrics use the union of all selected boundary features.",
                "Overlapping HUC, utility and inventory class summaries are not additive.",
                "Source acquisition scope and source geometry footprint have separate meanings.",
                "NWI occurrence remains visible under unknown, No_Data or conflicting mapping status.",
                "Intersection describes spatial context; it does not infer flow routing or ecological function.",
                "The original native GIS sources and their Z/M or curve lineage remain in the Workspace.",
            ])
            atomic_bytes(pending / "README.md", _readme(record).encode("utf-8"))
            archive_state = {**record, "state": "complete", "files": {
                path.name: describe_file(pending, path)
                for path in sorted(pending.iterdir()) if path.is_file()}}
            atomic_json(pending / "analysis-record.json", archive_state)
            with zipfile.ZipFile(pending / "context-analysis.zip", "w",
                                 compression=zipfile.ZIP_DEFLATED, compresslevel=6) as archive:
                for path in sorted(pending.iterdir()):
                    if path.is_file() and path.name != "context-analysis.zip":
                        archive.write(path, arcname=path.name)
            files = {}
            file_keys = {
                "selection.json": "selection", "summary.json": "summary_json",
                "summary.csv": "summary_csv", "sources.json": "sources",
                "geometry-corrections.json": "geometry_corrections",
                "boundary-summaries.json": "boundary_summaries_json",
                "boundary-summaries.csv": "boundary_summaries_csv",
                "preview.json": "preview", "features.geojson": "geojson",
                "features.csv": "features_csv", "relationships.csv": "relationships_csv",
                "README.md": "readme", "analysis-record.json": "portable_record",
                "context-analysis.zip": "archive",
            }
            for name, file_key in file_keys.items():
                source_path = pending / name
                destination = directory / name
                source_path.replace(destination)
                files[file_key] = describe_file(directory, destination)
            record.update(state="complete", files=files, completed_at=now(), updated_at=now(),
                          error=None)
            atomic_json(state_path, record)
            return record
        except Exception as error:
            record.update(state="failed", updated_at=now(),
                          error={"type": type(error).__name__, "message": str(error)})
            atomic_json(state_path, record)
            raise
        finally:
            shutil.rmtree(pending, ignore_errors=True)

"""Original annual-reference intake through the existing operator queue."""
from __future__ import annotations

from pathlib import Path
import re

from model.common import (atomic_bytes, atomic_json, describe_file, held,
                          identifier, now, read_json, relative_file, verify_file)
from source_tools import usgs_annual as annual
from source_preparation import SourcePreparation

ACTIONS = frozenset({"annual-reference.inventory", "annual-reference.import"})
APPLICATION = Path(__file__).resolve().parents[1]
DICTIONARY = APPLICATION / "source/usgs-annual2012-20261013/F7DN436B-original-metadata.xml"
BASINS = APPLICATION / "source/usgs-nldi-upper-savannah-20261013"
DEFAULT_HUCS = [f"030601{i:02d}" for i in range(1, 8)]


class AnnualReferences:
    def __init__(self, operator, fault, source_roots=()):
        self.operator, self.Fault = operator, fault
        self.sources = SourcePreparation(operator, fault, source_roots)

    def _fail(self, message, status=422):
        raise self.Fault("ANNUAL_REFERENCE", message, status)

    @staticmethod
    def _directory(workspace, task_id):
        return workspace.root / "annual-references" / identifier(task_id)

    def _record(self, workspace, task_id):
        directory = self._directory(workspace, task_id)
        record = read_json(directory / "operation.json")
        if record["project_id"] != workspace.project["id"]:
            self._fail("Choose an annual-reference operation in this workspace.")
        return directory, record

    def _all(self, workspace):
        return [read_json(path) for path in
                sorted((workspace.root / "annual-references").glob("*/operation.json"))]

    @staticmethod
    def _summary(record):
        result = record.get("result") or {}
        return {key: record.get(key) for key in
                ("task_id", "title", "action", "state", "stage", "updated_at", "error")} | {
                    "record_counts": result.get("record_counts"),
                    "usable_counts": result.get("usable_counts"),
                    "station_count": result.get("station_count"),
                    "binding": result.get("binding"),
                    "inventory_task_id": result.get("inventory_task_id"),
                }

    def _basin_sources(self):
        if not (BASINS / "source-manifest.json").is_file():
            return {}, {}
        manifest = read_json(BASINS / "source-manifest.json")
        review = read_json(BASINS / manifest["geometry_review"])
        sources = {}
        for item in manifest["original_sources"]:
            if item.get("comid"):
                sources[(item["comid"], item["kind"])] = item
        reviews = {row["current_nldi_comid"]: row for row in review["review"]}
        return sources, reviews

    def _choices(self, row, sources, reviews):
        choices = []
        comid = row.get("comid", "")
        if ((comid, "reach_feature") in sources and (comid, "upstream_basin") in sources
                and comid in reviews):
            review = reviews[comid]
            choices.append({
                "id": "retained-reach", "label": "Retained published reach " + comid,
                "description": "Original full-reach NLDI catchment; reviewed original component "
                               + str(review["retained_component_index"]) + ".",
                "component_review": review,
            })
        if re.fullmatch(r"[0-9]+", comid):
            choices.append({"id": "published-reach", "label": "Receive published reach " + comid,
                            "description": "Receive the original full-reach NLDI basin."})
        for key, choice, label in (
                ("station_id", "water-quality-station", "Water-quality station"),
                ("flow_station_id", "flow-station", "Published flow station")):
            station = row.get(key, "").removeprefix("USGS-")
            if re.fullmatch(r"[0-9]{8,15}", station):
                choices.append({"id": choice, "label": label + " " + station,
                                "description": "Receive the full original NLDI catchment for this source station."})
        return choices

    def _inventory(self, workspace, task_id):
        directory, record = self._record(workspace, task_id)
        if record["action"] != "annual-reference.inventory" or record["state"] != "complete":
            self._fail("Choose a completed original annual-source inventory.")
        path = directory / "inventory.json"
        verify_file(workspace.root, record["result"]["inventory"])
        value = read_json(path)
        # Verify the original ZIPs and dictionary again before displaying/adopting rows.
        if annual._source(directory / "original")["id"] != value["source"]["id"]:
            self._fail("The retained original inventory source has changed.")
        return directory, value

    def read(self, workspace_key, operation, payload=None):
        workspace = self.operator.ws(workspace_key)
        payload = payload or {}
        if operation == "catalog":
            return {
                "workspace_key": workspace_key, "default_huc8": DEFAULT_HUCS,
                "source_roots": [{"id": key, "label": str(path)}
                                 for key, path in self.sources.roots.items()],
                "uploads": [
                    {"id": row["id"], "filename": row["filename"], "bytes": row["bytes"]}
                    for path in sorted((self.operator.root / "uploads").glob("*.json"))
                    for row in [read_json(path)]
                    if row.get("bytes") in (781822, 519872)
                ],
                "operations": [self._summary(row) for row in self._all(workspace)],
                "dictionary_available": DICTIONARY.is_file(),
            }
        if operation == "files":
            return {"workspace_key": workspace_key, **self.sources._files(payload)}
        task_id = identifier(payload.get("task_id"))
        if operation == "inventory":
            _, value = self._inventory(workspace, task_id)
            sources, reviews = self._basin_sources()
            records = [{**row, "catchment_choices": self._choices(row, sources, reviews)}
                       for row in value["records"]]
            return {"workspace_key": workspace_key, "task_id": task_id, **value, "records": records}
        directory, record = self._record(workspace, task_id)
        if operation == "operation":
            return {"workspace_key": workspace_key, **record,
                    "_downloads": self._downloads(workspace_key, workspace, directory, record)}
        self._fail("Choose an annual-reference catalogue, inventory or operation.")

    def state(self, workspace_key):
        workspace = self.operator.ws(workspace_key)
        return {"operations": [self._summary(row) for row in self._all(workspace)]}

    def _downloads(self, workspace_key, workspace, directory, record):
        paths = [directory / "operation.json"]
        result = record.get("result") or {}
        for item in result.get("documents", []):
            verify_file(workspace.root, item)
            paths.append(relative_file(workspace.root, item["path"]))
        return [self.operator._ticket(workspace_key, path, describe_file(workspace.root, path),
                                      path.name) for path in paths if path.is_file()]

    def decorate_task(self, task):
        if task.get("action") not in ACTIONS:
            return task
        workspace = self.operator.ws(task["workspace"])
        directory = self._directory(workspace, task["id"])
        if not (directory / "operation.json").is_file():
            return task
        record = read_json(directory / "operation.json")
        task["_annual_reference"] = self._summary(record)
        task.setdefault("_downloads", []).extend(
            self._downloads(task["workspace"], workspace, directory, record))
        return task

    def _stage(self, directory, record, label):
        record.update(state="running", stage=label, updated_at=now())
        atomic_json(directory / "operation.json", record)

    def _original(self, workspace, directory, payload):
        original = directory / "original"
        original.mkdir(parents=True, exist_ok=True)
        mode = payload.get("mode", "registered")
        if mode == "published":
            annual.receive(original)
            return original
        if mode == "registered":
            source = self.sources._root_path(payload.get("root_id"), payload.get("path", ""), directory=True)
            supplied = {name: relative_file(source, name) for name in ("load_est.zip", "sitegage.zip")}
        elif mode == "uploads":
            supplied = {}
            for name, field in (("load_est.zip", "load_upload_id"), ("sitegage.zip", "site_upload_id")):
                upload = self.operator.upload(identifier(payload.get(field)))
                supplied[name] = Path(upload["path"])
        else:
            self._fail("Choose received originals, original uploads or the fixed published archive source.")
        for name, source in {**supplied, "F7DN436B-original-metadata.xml": DICTIONARY}.items():
            if source.stat().st_size != annual.FILES[name]["bytes"]:
                self._fail("The selected original has a different published length: " + name)
            atomic_bytes(original / name, source.read_bytes(), immutable=True)
        annual.receive(original)
        return original

    def _run_inventory(self, workspace, directory, record, payload):
        self._stage(directory, record, "Receiving original annual tables")
        original = self._original(workspace, directory, payload)
        selected_hucs = payload.get("huc8", DEFAULT_HUCS)
        if (not isinstance(selected_hucs, list) or not selected_hucs
                or any(not isinstance(value, str) or not re.fullmatch(r"[0-9]{8}", value)
                       for value in selected_hucs)):
            self._fail("Choose at least one original eight-digit HUC.")
        self._stage(directory, record, "Reading original station, estimator and period records")
        value = annual.inventory(original, huc8=selected_hucs)
        atomic_json(directory / "inventory.json", value, immutable=True)
        document = describe_file(workspace.root, directory / "inventory.json")
        return {"inventory": document, "documents": [document],
                "source_id": value["source"]["id"], "record_counts": value["record_counts"],
                "usable_counts": value["usable_counts"], "station_count": value["station_count"]}

    def _selection(self, original, inventory, payload):
        submitted = payload.get("records")
        if not isinstance(submitted, list) or not submitted:
            self._fail("Choose actual annual-reference records from the inventory.")
        by_id = {row["record_id"]: row for row in inventory["records"]}
        sources, reviews = self._basin_sources()
        selected, seen = [], set()
        for item in submitted:
            record_id = item.get("record_id") if isinstance(item, dict) else None
            if record_id not in by_id or record_id in seen:
                self._fail("Choose each inventory record once.")
            seen.add(record_id)
            row = by_id[record_id]
            if row["issues"]:
                self._fail("The selected original record has unresolved source fields: " + row["station_id"])
            choice = item.get("catchment")
            available = {item["id"] for item in self._choices(row, sources, reviews)}
            if choice not in available:
                self._fail("Choose an available original station or published reach for " + row["station_id"])
            spec = {"record_id": record_id,
                    "comparability_note": str(payload.get("comparability_note", "")).strip()}
            if choice == "retained-reach":
                comid, review = row["comid"], reviews[row["comid"]]
                retained = {"source": "comid", "identifier": comid, "station_role": "published_reach",
                            "split_catchment": False, "component_indices": [review["retained_component_index"]],
                            "component_selection_reason":
                                "Retain the original component containing the actual station and main upstream "
                                "basin, as documented in the original geometry review; retain omitted "
                                "component geometry and ellipsoidal area with the annual reference."}
                for kind, source_kind in (("feature", "reach_feature"), ("basin", "upstream_basin")):
                    item = sources[(comid, source_kind)]
                    verify_file(BASINS, item)
                    target = original / "nldi" / item["path"]
                    atomic_bytes(target, relative_file(BASINS, item["path"]).read_bytes(), immutable=True)
                    retained[kind] = {**describe_file(original, target), "uri": item["url"]}
                spec["retained_catchment"] = retained
            else:
                source, key, role = {
                    "published-reach": ("comid", "comid", "published_reach"),
                    "water-quality-station": ("nwissite", "station_id", "water_quality_station"),
                    "flow-station": ("nwissite", "flow_station_id", "published_flow_station"),
                }[choice]
                target = row[key] if source == "comid" else "USGS-" + row[key].removeprefix("USGS-")
                spec["catchment"] = {"source": source, "identifier": target,
                                     "station_role": role, "split_catchment": False}
            selected.append(spec)
        title = str(payload.get("title", "")).strip()
        if not title:
            self._fail("Give this selected observation edition a title.")
        return {"schema": annual.SELECTION_SCHEMA, "title": title,
                "source_id": inventory["source"]["id"], "records": selected,
                "scope": {"huc8": inventory["selected_huc8"],
                          "selection": "Original paired station/flow-station HUC8 records"}}

    def _run_import(self, workspace, directory, record, payload):
        inventory_task_id = identifier(payload.get("inventory_task_id"))
        previous, inventory = self._inventory(workspace, inventory_task_id)
        original = previous / "original"
        self._stage(directory, record, "Retaining the selected original catchment sources")
        selection = self._selection(original, inventory, payload)
        atomic_json(directory / "selection.json", selection, immutable=True)
        prepared = directory / "prepared"
        self._stage(directory, record, "Preparing selected annual loads and upstream catchments")
        result = annual.prepare(prepared, original_root=original,
                                selection_path=directory / "selection.json")
        self._stage(directory, record, "Importing the source edition and annual observations")
        binding = annual.bind(workspace.root, prepared)
        documents = [describe_file(workspace.root, directory / "selection.json")]
        documents.extend(describe_file(workspace.root, prepared / filename)
                         for filename in ("annual-loads.csv", "annual-records.json", "catchments.geojson",
                                          "catchment-sources.json", "observation-metadata.json",
                                          "source-manifest.json", "result.json",
                                          "binding-" + workspace.project["id"] + ".json"))
        return {"inventory_task_id": inventory_task_id, "binding": binding,
                "preparation_id": result["id"], "documents": documents,
                "records": result["records"], "stations": result["stations"],
                "catchments": result["catchments"], "parameters": result["parameters"]}

    def invoke(self, task):
        if task["action"] not in ACTIONS:
            self._fail("Choose an annual-reference intake action.")
        workspace = self.operator.ws(task["workspace"])
        directory = self._directory(workspace, task["id"])
        directory.mkdir(parents=True, exist_ok=True)
        with held(directory / ".operation.lock", blocking=False):
            path = directory / "operation.json"
            record = read_json(path) if path.exists() else {
                "schema": "upstate.annual-reference-operation/v1", "task_id": task["id"],
                "project_id": workspace.project["id"], "action": task["action"],
                "request_sha256": task["request_sha256"], "created_at": now(),
                "title": task["payload"].get("title") or "Original annual-reference inventory",
                "state": "queued", "updated_at": now(),
            }
            if (record["project_id"] != workspace.project["id"]
                    or record["request_sha256"] != task["request_sha256"]):
                self._fail("This retained operation belongs to a different source selection.")
            if record["state"] == "complete":
                return record["result"]
            try:
                function = self._run_inventory if task["action"] == "annual-reference.inventory" else self._run_import
                result = function(workspace, directory, record, task["payload"])
            except BaseException as error:
                record.update(state="failed", updated_at=now(),
                              error={"code": type(error).__name__, "message": str(error)})
                atomic_json(path, record)
                raise
            record.update(state="complete", stage="complete", result=result, updated_at=now())
            record.pop("error", None)
            atomic_json(path, record)
            return result

