class WaterContextService:
    """Explicit provider for the application's extension registry."""

    def __init__(self, operator, fault):
        self.operator = operator
        self.fault = fault

    def _fail(self, code, message, status=422):
        raise self.fault(code, message, status)

    def _payload(self, value):
        if value is None:
            return {}
        if not isinstance(value, dict):
            self._fail("WATER_CONTEXT_INPUT", "Supply a context input object.")
        return value

    def _analysis_id(self, payload):
        values = [payload[key] for key in ("analysis_id", "id", "view_id")
                  if payload.get(key) is not None]
        if not values:
            self._fail("WATER_CONTEXT_ANALYSIS", "Select a saved context analysis.")
        if any(value != values[0] for value in values[1:]):
            self._fail("WATER_CONTEXT_ANALYSIS", "Select one saved context analysis.")
        try:
            return identifier(values[0])
        except (ValueError, TypeError) as error:
            self._fail("WATER_CONTEXT_ANALYSIS", str(error))

    def _record(self, workspace, key):
        try:
            return water_context.get_saved(workspace, key)
        except FileNotFoundError:
            self._fail("WATER_CONTEXT_MISSING", "The selected context analysis is absent.", 404)
        except (ValueError, KeyError) as error:
            self._fail("WATER_CONTEXT_RECORD", str(error))

    def _selection(self, workspace, payload):
        has_selection = payload.get("selection") is not None
        has_id = payload.get("selection_id") is not None
        if has_selection == has_id:
            self._fail("WATER_CONTEXT_SELECTION",
                       "Supply a source selection or a saved selection ID.")
        if has_selection:
            value = payload["selection"]
        else:
            try:
                value = workspace._get("water-context-selections",
                                       identifier(payload["selection_id"]))
            except FileNotFoundError:
                self._fail("WATER_CONTEXT_SELECTION", "The saved context selection is absent.", 404)
            except (ValueError, TypeError) as error:
                self._fail("WATER_CONTEXT_SELECTION", str(error))
            value = {key: item for key, item in value.items() if key not in ("id", "schema")}
        if not isinstance(value, dict):
            self._fail("WATER_CONTEXT_SELECTION", "Supply a context source selection object.")
        return value

    def _downloads(self, workspace_key, workspace, record):
        if record.get("state") != "complete":
            return []
        directory = workspace.root / "water-context" / identifier(record["id"])
        result = []
        files = record.get("files", {})
        ordered = [key for key in FILE_ORDER if key in files]
        ordered.extend(sorted(set(files) - set(ordered)))
        for key in ordered:
            expected = files[key]
            path = relative_file(directory, expected["path"])
            ticket = self.operator._ticket(workspace_key, path, expected,
                                           FILE_LABELS.get(key, path.name))
            result.append({**ticket, "artifact": key})
        return result

    def state(self, workspace_key):
        """State refresh reads saved JSON metadata; original GIS files stay closed."""
        workspace = self.operator.ws(workspace_key)
        return {"schema": STATE_SCHEMA, "method": water_context.METHOD,
                "analyses": water_context.list_saved(workspace)}

    def read(self, workspace_key, operation, payload=None):
        workspace = self.operator.ws(workspace_key)
        payload = self._payload(payload)
        if operation == "catalog":
            return water_context.catalog(workspace)
        if operation == "list":
            return self.state(workspace_key)
        if operation not in ("analysis", "preview"):
            self._fail("WATER_CONTEXT_OPERATION", "Choose a registered context read operation.", 404)
        key = self._analysis_id(payload)
        record = self._record(workspace, key)
        if operation == "preview":
            try:
                return water_context.preview(workspace, key)
            except (ValueError, FileNotFoundError, KeyError) as error:
                self._fail("WATER_CONTEXT_PREVIEW", str(error))
        value = {**record, "_downloads": self._downloads(workspace_key, workspace, record),
                 "boundary_summaries": []}
        if record.get("state") == "complete":
            directory = workspace.root / "water-context" / key
            try:
                path = verify_file(directory, record["files"]["boundary_summaries_json"])
                value["boundary_summaries"] = read_json(path)["boundaries"]
            except (ValueError, FileNotFoundError, KeyError) as error:
                self._fail("WATER_CONTEXT_EXPORT", str(error))
        return value

    def invoke(self, task):
        if task.get("action") != ACTION:
            self._fail("WATER_CONTEXT_ACTION", "This provider handles context builds.", 404)
        workspace = self.operator.ws(task["workspace"])
        payload = self._payload(task.get("payload"))
        selection = self._selection(workspace, payload)
        record = water_context.build(workspace, selection)
        return {"kind": ITEM_KIND, "id": record["id"], "analysis_id": record["id"],
                "title": record["title"], "state": record["state"],
                "selection_id": record["selection_id"], "summary": record["summary"]}

    def decorate_task(self, task):
        """Register original verified tickets without rehashing on task refresh."""
        if task.get("action") != ACTION or task.get("state") != "complete":
            return task
        result = task.get("result") or {}
        key = result.get("analysis_id") or result.get("id")
        if not key:
            return task
        workspace_key = task["workspace"]
        workspace = self.operator.ws(workspace_key)
        record = self._record(workspace, identifier(key))
        task["_downloads"] = self._downloads(workspace_key, workspace, record)
        return task

    def verify_workspace(self, workspace):
        """Inspect retained analyses through the existing explicit receiving flow."""
        result = water_context.verify_all(workspace)
        unfinished = [row for row in result["errors"]
                      if row.get("state") in ("building", "failed")
                      and row.get("error") == "Analysis exports are not complete"]
        errors = [row for row in result["errors"] if row not in unfinished]
        if errors:
            details = "; ".join(row["id"] + ": " + row["error"] for row in errors[:5])
            self._fail("WATER_CONTEXT_RECEIVE", "Context archive verification failed: " + details)
        return {**result, "ok": True, "errors": [], "unfinished": unfinished}

/** Original USGS annual references on the current scientific operator. */
const esc = value => String(value ?? '').replace(/[&<>"']/g, value =>
  ({'&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'}[value]));
const short = value => String(value ?? '').slice(0, 12);
const number = value => Number.isFinite(value) ?
  value.toLocaleString(undefined, {maximumSignificantDigits:7}) : '—';
const select = (name, values, selected='', attributes='') =>
  '<select name="'+esc(name)+'" '+attributes+'>'+values.map(([id, label]) =>
  '<option value="'+esc(id)+'" '+(id===selected?'selected':'')+'>'+esc(label)+'</option>').join('')+'</select>';
const field = (label, body, help='') => '<label><span>'+esc(label)+'</span>'+body+
  (help?'<small>'+esc(help)+'</small>':'')+'</label>';
const action = (name, label, id='', extra='') => '<button type="button" data-annual-action="'+esc(name)+
  '" data-id="'+esc(id)+'" '+extra+'>'+esc(label)+'</button>';
const table = (heads, rows) => '<div class="annual-table"><table><thead><tr>'+
  heads.map(label=>'<th scope="col">'+esc(label)+'</th>').join('')+
  '</tr></thead><tbody>'+rows.join('')+'</tbody></table></div>';

export function createAnnualReferences(host) {
  let root=null, workspace=null, epoch=0, catalog=null, inventory=null, error='', pending=false;
  let chosen=new Map(), query='', series='', page=0, loading=null, taskSignature='';
  let files=null, browsing=false;
  const defaults={mode:'registered',root_id:'',path:'',load_upload_id:'',site_upload_id:'',
    huc8:'03060101, 03060102, 03060103, 03060104, 03060105, 03060106, 03060107',
    title:'USGS annual-reference selection',comparability_note:''};
  const draft={mode:'registered', root_id:'', path:'', load_upload_id:'', site_upload_id:'',
    huc8:'03060101, 03060102, 03060103, 03060104, 03060105, 03060106, 03060107',
    title:'USGS annual-reference selection', comparability_note:''};
  const current = () => host.getState()?.workspace_key;
  const key = () => 'upstate-annual-reference:'+workspace;
  function save() {
    try { sessionStorage.setItem(key(), JSON.stringify({draft, selected:[...chosen], query, series,
      inventory_task_id:inventory?.task_id})); } catch (_) { /* Retained native tasks remain authoritative. */ }
  }
  function restore() {
    try {
      const value=JSON.parse(sessionStorage.getItem(key()) || 'null');
      if (!value) return null;
      for(const name of Object.keys(draft)) if(typeof value.draft?.[name]==='string') draft[name]=value.draft[name];
      chosen=new Map(Array.isArray(value.selected)?value.selected:[]);
      query=value.query||''; series=value.series||'';
      return value.inventory_task_id||null;
    } catch (_) { return null; }
  }
  function still(token, selected) { return root && token===epoch && selected===workspace && current()===workspace; }
  async function read(operation, values={}) {
    const token=epoch, selected=workspace;
    const value=await host.api(host.endpoint('/api/annual-references/'+operation, values));
    if (!still(token, selected)) throw Error('The workspace changed. Open its annual references again.');
    return value;
  }
  async function refresh() {
    if (!root || current()!==workspace) return;
    if (loading) return loading;
    const token=epoch, selected=workspace;
    loading=(async () => {
      try {
        const value=await read('catalog');
        if(!still(token, selected)) return;
        catalog=value;
        if(!draft.root_id && value.source_roots.length) draft.root_id=value.source_roots[0].id;
        if(draft.mode==='registered' && !value.source_roots.length) draft.mode='published';
        error='';
        render();
      } catch(err) { if(still(token, selected)){error=err.message;render();} }
      finally { if(still(token, selected)) loading=null; }
    })();
    return loading;
  }
  async function openInventory(id) {
    const value=await read('inventory', {task_id:id});
    if(inventory?.task_id && inventory.task_id!==id) chosen=new Map();
    inventory=value; page=0;
    const rows=new Map(value.records.map(row=>[row.record_id,row]));
    chosen=new Map([...chosen].filter(([id, choice]) =>
      rows.has(id) && rows.get(id).catchment_choices.some(item=>item.id===choice)));
    save(); render();
  }
  function selectedRows() {
    return (inventory?.records || []).filter(row=>chosen.has(row.record_id));
  }
  function rows() {
    const token=query.trim().toLowerCase();
    return (inventory?.records || []).filter(row=>
      (!series || row.series===series) && (!token ||
       [row.station_id,row.station_name,row.flow_station_id,row.comid,...row.huc8].join(' ').toLowerCase().includes(token)));
  }
  function sourceForm() {
    const roots=(catalog?.source_roots || []).map(row=>[row.id,row.label]);
    const mode=select('mode', [['registered','Use received originals'],['uploads','Use original ZIP uploads'],
                             ['published','Receive the published originals']],draft.mode);
    let selected='';
    if(draft.mode==='registered') {
      selected=field('Registered source folder', select('root_id',[['','Choose source folder'],...roots],draft.root_id))+
        field('Directory within that folder','<input name="path" value="'+esc(draft.path)+'">',
          'This directory must contain the complete load_est.zip and sitegage.zip originals.')+
        '<div class="annual-buttons">'+action('browse','Browse directories')+'</div>';
    } else if(draft.mode==='uploads') {
      const options=bytes=>[['','Choose original ZIP'],...(catalog?.uploads || [])
        .filter(row=>row.bytes===bytes).map(row=>[row.id,row.filename+' · '+row.bytes.toLocaleString()+' bytes'])];
      selected=field('Published load estimates',select('load_upload_id',options(781822),draft.load_upload_id))+
        field('Paired station and flow records',select('site_upload_id',options(519872),draft.site_upload_id))+
        '<p class="annual-help">Select the complete originals already added through this operator’s upload flow.</p>';
    } else {
      selected='<p class="annual-help">The existing native queue receives the two fixed USGS source archives and their original dictionary. Completed original files are reused when the task resumes.</p>';
    }
    return '<section class="section"><h2>Original annual-load source</h2><p>USGS F7DN436B publishes long-term mean annual estimates with a 2012 reference year. Its original estimator, uncertainty and sampling periods travel with each selected observation.</p>'+
      '<div class="annual-fields">'+field('Source intake',mode)+selected+
      field('Source HUC8 selection','<input name="huc8" value="'+esc(draft.huc8)+'">',
        'Use comma-separated original eight-digit HUC codes. The default covers the seven Upper Savannah HUC8s.')+
      '</div>'+directoryBrowser()+'<div class="annual-buttons">'+action('inventory','Read original station records','',
        pending?'disabled':'class="primary"')+'</div></section>';
  }
  function directoryBrowser() {
    if(!browsing) return '';
    if(!files) return '<p role="status">Reading source directories…</p>';
    const parent=files.path.split('/').slice(0,-1).join('/');
    return '<div class="annual-browser"><h3>Registered source directory</h3><p class="mono">'+esc(files.path||'/')+
      '</p><div class="annual-buttons">'+(files.path?action('directory','Parent directory',parent):'')+
      action('choose-directory','Use this directory',files.path)+action('close-browser','Close')+'</div>'+
      '<ul>'+files.entries.filter(row=>row.is_dir).map(row=>'<li>'+action('directory',row.name,row.path)+'</li>').join('')+
      '</ul><p>'+files.entries.filter(row=>!row.is_dir).map(row=>esc(row.name)).join(' · ')+
      '</p>'+(files.next_offset!==null?action('directory-next','More directory entries',String(files.next_offset)):'')+'</div>';
  }
  function savedOperations() {
    const operations=catalog?.operations || [];
    if(!operations.length) return '<section class="section"><h2>Retained source operations</h2><p>Completed source inventories and imported observation editions appear here.</p></section>';
    return '<section class="section"><h2>Retained source operations</h2>'+
      table(['Operation','State','Original records',''],[...operations].reverse().map(row=>{
        const counts=row.record_counts?Object.entries(row.record_counts).map(([name,count])=>name.toUpperCase()+': '+count).join(' · '):'';
        const binding=row.binding;
        const open=row.action==='annual-reference.inventory' && row.state==='complete'?
          action('open-inventory','Select records',row.task_id):'';
        const calibrate=binding?action('calibrate','Open calibration',row.task_id):'';
        return '<tr><td><strong>'+esc(row.title)+'</strong><small>'+esc(short(row.task_id))+'</small></td><td>'+
          esc(row.state)+(row.stage&&row.stage!=='complete'?'<small>'+esc(row.stage)+'</small>':'')+
          (row.error?'<small>'+esc(row.error.message)+'</small>':'')+'</td><td>'+
          esc(binding?String(binding.admitted_count)+' imported':counts)+'</td><td><div class="annual-buttons">'+
          open+calibrate+action('task','Open operation',row.task_id)+'</div></td></tr>';
      }))+'</section>';
  }
  function recordTable() {
    if(!inventory) return '';
    const filtered=rows(), pages=Math.max(1,Math.ceil(filtered.length/40));
    page=Math.max(0,Math.min(page,pages-1));
    const visible=filtered.slice(page*40,page*40+40);
    const reviewRows=visible.map(row=>{
      const possible=row.catchment_choices || [], selected=chosen.has(row.record_id);
      const choice=chosen.get(row.record_id)||possible[0]?.id||'';
      const unavailable=row.issues.length || !possible.length;
      return '<tr><td><input type="checkbox" name="record" value="'+esc(row.record_id)+'" aria-label="Select '+
        esc(row.station_id+' '+row.series)+'" '+(selected?'checked':'')+' '+(unavailable?'disabled':'')+
        '></td><td><strong>'+esc(row.station_name||row.station_id)+'</strong><small>'+
        esc(row.station_id)+' · flow '+esc(row.flow_station_id)+'</small><small>HUC '+esc(row.huc8.join(', '))+
        ' · COMID '+esc(row.comid)+'</small></td><td>'+esc(row.series.toUpperCase())+'<small>'+
        esc(row.parameter)+'</small></td><td>'+number(row.value)+'<small>kg/year · '+esc(row.final_method)+
        '</small><small>SE '+number(row.uncertainty?.value)+' kg/year</small></td><td>'+
        esc(row.temporal_basis?.flow_start_inclusive || row.period_start || '—')+'<small>through '+
        esc(row.temporal_basis?.flow_end_inclusive || '—')+'</small></td><td>'+
        (unavailable?'<p>'+esc(row.issues.join('; ') || 'No original USGS station/reach option in this row.')+'</p>':
          select('catchment',possible.map(item=>[item.id,item.label]),choice,'data-record="'+esc(row.record_id)+'"'))+
        '</td><td>'+action('record-detail','Original fields',row.record_id)+'</td></tr>';
    });
    const selected=selectedRows();
    return '<section class="section"><h2>Select original reference records</h2><p>'+
      inventory.station_count+' stations in the selected original HUC fields. '+selected.length+
      ' records selected. Each load is already an annual mass rate.</p>'+
      '<div class="annual-fields">'+field('Find a station, reach or HUC','<input name="query" value="'+esc(query)+'">')+
      field('Constituent',select('series',[['','All constituents'],['tn','Total nitrogen'],['tp','Total phosphorus'],
        ['ssc','Suspended sediment'],['tss','Total suspended solids']],series))+'</div>'+
      '<div class="annual-buttons">'+action('select-visible','Select usable records on this page')+
      action('clear-selection','Clear selection')+'</div>'+
      table(['Use','Original station','Constituent','Published estimate','Included flow period','Catchment source',''],reviewRows)+
      '<div class="annual-buttons">'+action('previous','Previous page','',page===0?'disabled':'')+
      '<span>Page '+(page+1)+' of '+pages+' · '+filtered.length+' matching records</span>'+
      action('next','Next page','',page>=pages-1?'disabled':'')+'</div>'+
      '<p class="annual-help">Choose one sediment constituent per catchment: SSC and TSS retain distinct measurement definitions. Catchment geometry and source/model periods remain available in calibration.</p>'+
      '<div class="annual-fields">'+field('Observation edition title','<input name="title" value="'+esc(draft.title)+'">')+
      field('Study comparability note','<textarea name="comparability_note" rows="3">'+esc(draft.comparability_note)+'</textarea>',
        'Record the relevant relationship between these historical annual references and the selected model inputs.')+
      '</div><div class="annual-buttons">'+action('import','Import selected loads and catchments','',
        pending||!selected.length?'disabled':'class="primary"')+'</div></section>';
  }
  function render() {
    if(!root || workspace!==current() || root.querySelector('.annual-record-dialog')?.open) return;
    root.innerHTML='<div class="annual-reference"><header class="page-header"><div><p class="eyebrow">ORIGINAL ANNUAL REFERENCES</p>'+
      '<h1>Annual load observations</h1><p>Receive the published source, select its actual station records and carry those observations into native-model calibration.</p></div>'+
      action('refresh','Refresh')+'</header>'+(error?'<div class="annual-error" role="alert">'+esc(error)+'</div>':'')+
      (pending?'<p role="status">Submitting the selected operation…</p>':'')+
      (catalog?sourceForm()+recordTable()+savedOperations():'<p role="status">Loading annual-reference sources…</p>')+
      '<dialog class="annual-record-dialog"><div data-record-content></div><form method="dialog"><button>Close</button></form></dialog></div>';
  }
  function operationById(id) { return (catalog?.operations||[]).find(row=>row.task_id===id); }
  async function browse(path, offset=0) {
    if(!draft.root_id) throw Error('Choose a registered source folder first.');
    browsing=true; if(offset===0) files=null; render();
    files=await read('files',{root_id:draft.root_id,path,offset,limit:100});render();
  }
  function detail(id) {
    const row=inventory?.records.find(row=>row.record_id===id);
    if(!row) return;
    const dialog=root.querySelector('.annual-record-dialog');
    dialog.querySelector('[data-record-content]').innerHTML='<h2>'+esc(row.station_name||row.station_id)+
      ' · '+esc(row.series.toUpperCase())+'</h2><p>Published estimator: '+esc(row.final_method)+
      '. Original load field: '+esc(row.selected_load_field)+'.</p><p>'+
      'The included source period and original water-quality dates are retained below.</p><pre>'+esc(JSON.stringify(row,null,2))+'</pre>';
    dialog.addEventListener('close',()=>render(),{once:true});
    dialog.showModal();
  }
  async function perform(button) {
    const name=button.dataset.annualAction, id=button.dataset.id;
    if(name==='refresh') return refresh();
    if(name==='open-inventory') return openInventory(id);
    if(name==='task') return host.showTask(id);
    if(name==='browse') return browse(draft.path);
    if(name==='directory') return browse(id);
    if(name==='directory-next') return browse(files.path,Number(id));
    if(name==='choose-directory'){draft.path=id;browsing=false;files=null;save();return render();}
    if(name==='close-browser'){browsing=false;return render();}
    if(name==='record-detail') return detail(id);
    if(name==='previous'){page--;return render();}
    if(name==='next'){page++;return render();}
    if(name==='clear-selection'){chosen.clear();save();return render();}
    if(name==='select-visible'){
      for(const row of rows().slice(page*40,page*40+40)) if(!row.issues.length&&row.catchment_choices.length){
        chosen.set(row.record_id,chosen.get(row.record_id)||row.catchment_choices[0].id);
      }
      save();return render();
    }
    if(name==='calibrate'){
      const entry=operationById(id), binding=entry?.binding;
      if(!binding) throw Error('This operation has not imported an observation edition.');
      return host.openExtension('calibration','openForObservations',{
        observation_id:binding.observation_id,catchments:binding.catchments,
        temporal_weighting:binding.recommended_temporal_weighting,title:entry.title});
    }
    if(name==='inventory'){
      const huc8=draft.huc8.split(/[\s,;]+/).filter(Boolean);
      if(!huc8.length || huc8.some(value=>!/^[0-9]{8}$/.test(value))) throw Error('Enter the original eight-digit HUC codes.');
      if(draft.mode==='registered'&&!draft.root_id) throw Error('Choose the registered source folder.');
      if(draft.mode==='uploads'&&(!draft.load_upload_id||!draft.site_upload_id)) throw Error('Choose both original ZIP uploads.');
      pending=true;render();
      await host.submitAction('annual-reference.inventory',{mode:draft.mode,root_id:draft.root_id,path:draft.path,
        load_upload_id:draft.load_upload_id,site_upload_id:draft.site_upload_id,huc8,
        title:'USGS annual records · '+huc8.join(', ')});
      return;
    }
    if(name==='import'){
      const selected=selectedRows();
      if(!inventory || !selected.length || !draft.title.trim()) throw Error('Select source records and name the observation edition.');
      const uses=new Set();
      for(const row of selected) {
        const choice=chosen.get(row.record_id);
        const identity=choice.includes('reach')?'reach:'+row.comid:
          choice==='flow-station'?'station:'+row.flow_station_id:'station:'+row.station_id;
        const pair=identity+':'+row.parameter;
        if(uses.has(pair)) throw Error('Choose one original '+row.parameter+' series for '+row.station_id+
          '. SSC and TSS cannot both represent the same catchment.');
        uses.add(pair);
      }
      pending=true;render();
      await host.submitAction('annual-reference.import',{inventory_task_id:inventory.task_id,title:draft.title.trim(),
        comparability_note:draft.comparability_note,records:selected.map(row=>({
          record_id:row.record_id,catchment:chosen.get(row.record_id)}))});
    }
  }
  async function click(event) {
    const button=event.target.closest?.('[data-annual-action]');
    if(!button || !root?.contains(button) || button.disabled) return;
    event.preventDefault(); event.stopPropagation();
    if(pending) return;
    const token=epoch, selected=workspace;
    try { error='';await perform(button); }
    catch(err) { if(still(token,selected)) error=err.message||String(err); }
    finally { if(still(token,selected)){pending=false;render();} }
  }
  function change(event) {
    const element=event.target, name=element.name;
    if(name==='record') {
      const row=inventory?.records.find(row=>row.record_id===element.value);
      if(element.checked&&row) {
        const field=element.closest('tr').querySelector('[name="catchment"]');
        chosen.set(row.record_id,field.value);
      } else chosen.delete(element.value);
      save();render();return;
    }
    if(name==='catchment') {
      if(chosen.has(element.dataset.record)) chosen.set(element.dataset.record,element.value);
      save();return;
    }
    if(name==='series'){series=element.value;page=0;save();render();return;}
    if(Object.hasOwn(draft,name)) {
      draft[name]=element.value;
      if(name==='root_id'){draft.path='';files=null;browsing=false;}
      save();
      if(['mode','root_id'].includes(name)) render();
    }
  }
  function input(event) {
    const element=event.target;
    if(element.name==='query') {
      const position=element.selectionStart;
      query=element.value;page=0;save();render();
      const target=root.querySelector('[name="query"]');target.focus();target.setSelectionRange(position,position);
    } else if(Object.hasOwn(draft,element.name)) {draft[element.name]=element.value;save();}
  }
  async function mount(node) {
    detach();
    root=node;workspace=current();epoch++;
    Object.assign(draft,defaults);query='';series='';page=0;
    const savedInventory=restore(), token=epoch, selected=workspace;
    root.addEventListener('click',click);root.addEventListener('change',change);root.addEventListener('input',input);
    render();await refresh();
    if(savedInventory && still(token,selected)) {
      try {await openInventory(savedInventory);} catch(err){if(still(token,selected)){error=err.message;render();}}
    }
  }
  function update(state) {
    if(!root || workspace!==state?.workspace_key) return;
    const value=state?.data?.annual_references?.operations || [];
    const signature=JSON.stringify(value.map(row=>[row.task_id,row.state,row.updated_at]));
    if(signature!==taskSignature){taskSignature=signature;void refresh();}
  }
  function detach() {
    if(root){root.removeEventListener('click',click);root.removeEventListener('change',change);root.removeEventListener('input',input);}
    root=null;workspace=null;catalog=null;inventory=null;chosen=new Map();error='';pending=false;
    files=null;browsing=false;loading=null;taskSignature='';epoch++;
  }
  return {mount,update,detach};
}

/* Original-catchment residual maps inside the maintained Calibration desk. */
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const short=value=>value?String(value).slice(0,12):'—';
const human=value=>String(value??'').replaceAll('_',' ');
const count=value=>Array.isArray(value)?value.length:Number.isFinite(value)?value:0;
const number=value=>Number.isFinite(value)?value.toLocaleString(undefined,{maximumSignificantDigits:7}):'—';
const json=value=>JSON.stringify(value,null,2);
const button=(action,label,id='',extra='')=>'<button type="button" class="small" data-action="calibration-maps-'+esc(action)+'"'+(id?' data-id="'+esc(id)+'"':'')+' '+extra+'>'+esc(label)+'</button>';
const table=(headers,rows)=>'<div class="table-scroll"><table><thead><tr>'+headers.map(v=>'<th scope="col">'+esc(v)+'</th>').join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table></div>';
const section=(title,description,body,actions='')=>'<section class="section"><header class="section-header"><div><h2>'+esc(title)+'</h2><p>'+esc(description)+'</p></div><div class="page-actions">'+actions+'</div></header>'+body+'</section>';
const spatialButton=(kind,id,label,collection='')=>'<button type="button" class="small" data-action="spatial-item" data-kind="'+esc(kind)+'" data-id="'+esc(id)+'"'+(collection?' data-collection="'+esc(collection)+'"':'')+'>'+esc(label)+'</button>';

/** Views and actions share the parent's workspace and request-generation guard. */
export function createCalibrationMaps({current,read,submitAction,openForm,fileList,detail,repaint,
    getReport,getUncertainty,getData,openReport,openUncertainty,activate}){
  let packet=null,request=0,formRequest=0,filter='',selectedLayer=null;
  const active=()=>packet?.workspace_key===current();
  const maps=()=>getData().calibration_maps??[];
  const reviewLinks=()=>getData().calibration_map_reviews??[];
  function reset(){packet=null;request++;formRequest++;filter='';selectedLayer=null;}
  function invalidate(){request++;formRequest++;}
  function sync(){
    if(packet&&packet.workspace_key!==current()){reset();return true;}
    if(!active())return false;
    const links=reviewLinks().filter(row=>row.map_id===packet.map.id);
    if(JSON.stringify(links)===JSON.stringify(packet.reviews??[]))return false;
    packet.reviews=links;return true;
  }
  function summary(reportId,uncertaintyId=null){
    const records=[...new Map([...(getReport()?.maps??[]),...maps()].filter(row=>row.calibration_id===reportId).map(row=>[row.id,row])).values()];
    const action=button('prepare',uncertaintyId?'Map these reference ranges':'Prepare residual maps',reportId,
      uncertaintyId?'data-uncertainty="'+esc(uncertaintyId)+'"':'');
    return section('Catchment residual maps',
      'Original source geometry, retained annual loads and native residuals. The selected profile includes held-out descriptive rows; challenger layers contain calibration catchments.',
      records.length?table(['Saved map edition','Layers','Reference ranges',''],records.map(row=>
        '<tr><td><strong>'+esc(row.title||'Catchment residual maps')+'</strong><small class="mono">'+esc(short(row.id))+'</small></td><td>'+number(row.layer_count)+'</td><td>'+esc(row.uncertainty_id?'Retained published-error sensitivity':'Nominal reference loads')+'</td><td>'+button('open','Open maps',row.id)+'</td></tr>')):
      '<p class="calibration-empty">Prepare the original catchment layers and their PDF/SVG atlas from this completed calibration.</p>',action);
  }
  async function open(id){
    const workspace=current(),ticket=++request;
    const result=await read('maps',{id});
    if(ticket!==request||workspace!==current())return;
    packet=result;filter='';selectedLayer=result.map.layers?.[0]?.id??null;
    document.querySelector('#detail-dialog')?.close();
    activate();
  }
  async function prepareForm(reportId,uncertaintyId=null){
    const workspace=current(),ticket=++formRequest;
    const retained=getReport();
    const nominal=retained?.report?.id===reportId?retained:await read('report',{id:reportId});
    if(ticket!==formRequest||workspace!==current())return;
    const report=nominal.report;
    if(report.state!=='complete'||!report.selected_run_id)throw Error('Choose a completed calibration with an eligible selected native run.');
    const uncertainties=nominal.uncertainties??[];
    if(uncertaintyId&&!uncertainties.some(row=>row.id===uncertaintyId))throw Error('Choose an original sensitivity analysis belonging to this calibration.');
    const candidates=(report.ranked_candidates??[]).filter(row=>row.run_id!==report.selected_run_id);
    const selected=report.ranked_candidates.find(row=>row.run_id===report.selected_run_id);
    const content='<div class="calibration-form"><div class="form-grid">'+
      '<div class="full calibration-source"><h3>Original selected native run</h3><p>'+esc(selected?.title||short(report.selected_run_id))+
      ' · '+esc((selected?.selected_models??report.selected_models??[]).map(v=>v.toUpperCase()).join(' + '))+
      '</p><p>The selected run is always included. Its held-out rows stay descriptive. Added challengers contain calibration catchments only.</p></div>'+
      '<label class="full"><span>Published observation-error ranges</span><select name="calibration_maps_uncertainty"><option value="">Nominal reference loads</option>'+
      uncertainties.map(row=>'<option value="'+esc(row.id)+'" '+(row.id===uncertaintyId?'selected':'')+'>'+
        esc(number(row.standard_errors)+' published standard errors · '+human(row.state)+' · '+short(row.id))+'</option>').join('')+
      '</select><small>Use the exact retained sensitivity edition, including its original missing-error coverage.</small></label>'+
      '<div class="full"><h3>Optional challenger layers</h3>'+
      (candidates.length?table(['Include','Native candidate','Calibration loss'],candidates.map(row=>
        '<tr><td><input type="checkbox" name="calibration_maps_candidates" value="'+esc(row.run_id)+'" aria-label="Include '+esc(row.title||short(row.run_id))+'"></td><td><strong>'+esc(row.title||short(row.run_id))+'</strong><small>'+esc((row.selected_models??[]).map(v=>v.toUpperCase()).join(' + '))+' · '+esc(short(row.run_id))+'</small></td><td>'+number(row.objective_score)+'</td></tr>')):
        '<p>No other eligible native candidates are retained in this calibration.</p>')+'</div>'+
      '<div class="full calibration-source"><p>Each atlas page keeps the original catchment boundary, including holes and disconnected parts. Nested upstream catchments appear separately. A shared absolute-residual display cap is used per pollutant across the selected native candidates.</p><p>Ordinary source layers also retain the complete scalar attributes for spatial inspection and editable GIS export.</p></div></div></div>';
    openForm('Prepare catchment residual maps','Create retained map sources, CSV tables and a grayscale PDF/SVG atlas from the existing completed result.',content,'Prepare maps',async()=>{
      if(workspace!==current()||ticket!==formRequest)throw Error('The study or map selection changed. Reopen this form.');
      const form=document.querySelector('#operation-form');
      const chosen=[...form.querySelectorAll('[name="calibration_maps_candidates"]:checked')].map(input=>input.value);
      const allowed=new Set(candidates.map(row=>row.run_id));
      if(chosen.some(id=>!allowed.has(id)))throw Error('Choose candidate runs from this original calibration.');
      const uncertainty=form.querySelector('[name="calibration_maps_uncertainty"]').value;
      if(uncertainty&&!uncertainties.some(row=>row.id===uncertainty))throw Error('Choose a retained sensitivity edition from this calibration.');
      return submitAction('calibration.maps.prepare',{report_id:reportId,
        candidate_run_ids:[report.selected_run_id,...new Set(chosen)],uncertainty_id:uncertainty||null});
    });
  }
  function layer(id){
    const value=packet?.map?.layers?.find(row=>row.id===id);
    if(!active()||!value)throw Error('Open an original retained residual-map layer.');
    return value;
  }
  function sourceButton(value){return spatialButton('source-info',value.source_id,'Open source map',value.source_collection_id);}
  function reviewsFor(value){
    return (packet.reviews??[]).filter(row=>row.layer_id===value.id).map(row=>
      spatialButton('spatial_reviews',row.review_id,'Open saved review')).join('');
  }
  function ticketFor(expected){
    if(!expected)return null;
    return (packet.artifacts??[]).find(row=>row.file.path===expected.path&&row.file.sha256===expected.sha256)?.download??null;
  }
  function retainedFiles(files){
    return fileList(files).replaceAll('data-action="preview-file"','data-action="calibration-maps-preview"');
  }
  function preview(fileId){
    if(!active())throw Error('Open this workspace’s retained map edition.');
    const item=(packet.artifacts??[]).find(row=>row.download.id===fileId)?.download;
    if(!item||!item.filename.toLowerCase().endsWith('.pdf'))throw Error('Choose a retained PDF from this original map edition.');
    detail(item.label||item.filename,
      '<div class="preview-options"><span>'+esc(number(item.bytes))+' bytes · <span class="mono">'+esc(short(item.sha256))+'</span></span>'+
      '<a class="button" href="'+esc(item.url)+'?download=1" download>Download original PDF</a></div>'+
      '<iframe class="preview-frame" title="'+esc(item.filename)+'" src="'+esc(item.url)+'"></iframe>',
      {kind:'file',id:item.id});
  }
  function layerFiles(value){
    return [value.geojson,value.csv,value.pdf,...(value.svg_pages??[])].filter(Boolean).map(ticketFor).filter(Boolean);
  }
  function layerDetails(value){
    const files=layerFiles(value),pages=value.svg_pages??[];
    const selected=value.run_id===packet.map.selected_run_id;
    const previews=pages.map((file,index)=>{
      const ticket=ticketFor(file);
      return ticket?'<figure class="calibration-map-page"><img loading="lazy" src="'+esc(ticket.url)+'" alt="'+esc(value.title+' — original catchment residual atlas, page '+(index+1))+'"><figcaption>Page '+(index+1)+' · <a href="'+esc(ticket.url)+'?download=1" download>Download original SVG</a></figcaption></figure>':'';
    }).join('');
    return section(value.title||human(value.parameter)+' residuals',
      selected?'Original selected native run; calibration and held-out descriptive catchments retain their own support.':'Challenger native run; original calibration catchments only.',
      '<div class="cards">'+[
        ['Pollutant',human(value.parameter),value.units],
        ['Calibration rows',number(count(value.calibration_rows)),'Original catchment/pollutant rows.'],
        ['Held-out rows',number(count(value.validation_rows)),'Selected run only; outside parameter selection.'],
        ['Incomplete native rows',number(count(value.incomplete_native_rows)),'Retained with missing support rather than assigned zero.'],
        ['Residual display cap',number(value.absolute_residual_display_cap),value.units+' · shared across these candidate maps for this pollutant.']
      ].map(([label,v,note])=>'<div class="card"><h3>'+esc(label)+'</h3><strong class="calibration-card-value">'+esc(v)+'</strong><p>'+esc(note)+'</p></div>').join('')+'</div>'+
      '<div class="section-body"><p>The source viewer shows original boundaries and scalar attributes. The retained atlas renders signed residuals as separate catchment panels; overlapping basins are not added together.</p><div class="page-actions">'+
      sourceButton(value)+button('review','Save original spatial review',value.id)+reviewsFor(value)+'</div></div>'+
      retainedFiles(files)+(previews?'<div class="calibration-map-atlas">'+previews+'</div>':'')+
      '<details class="technical"><summary>Original layer identity, spatial selection and display scale</summary><pre class="json-view">'+
      esc(json({run_id:value.run_id,profile_id:value.profile_id,selected_models:value.selected_models,
        source_collection_id:value.source_collection_id,source_id:value.source_id,
        spatial_selection:value.spatial_selection,view:value.view,absolute_residual_display_cap:value.absolute_residual_display_cap}))+'</pre></details>');
  }
  function layerTable(){
    const values=(packet.map.layers??[]).filter(row=>!filter||json([row.title,row.parameter,row.units,row.run_id,row.profile_id]).toLowerCase().includes(filter.toLowerCase()));
    return table(['Original layer','Candidate role','Rows','Support',''],values.map(value=>'<tr'+(value.id===selectedLayer?' class="calibration-selected-row"':'')+'>'+
      '<td><strong>'+esc(value.title||human(value.parameter))+'</strong><small>'+esc(value.units)+' · '+esc(short(value.run_id))+'</small></td>'+
      '<td>'+esc(value.run_id===packet.map.selected_run_id?'Original selected':'Challenger: calibration only')+'</td>'+
      '<td>'+number(count(value.rows))+'</td><td>'+number(count(value.incomplete_native_rows))+' incomplete</td>'+
      '<td class="actions-cell">'+button('layer','Atlas and files',value.id)+sourceButton(value)+reviewsFor(value)+'</td></tr>'));
  }
  function render(){
    if(!active())return '';
    const map=packet.map,notes=Array.isArray(map.interpretation)?map.interpretation:[map.interpretation].filter(Boolean);
    const value=map.layers.find(row=>row.id===selectedLayer)??map.layers[0];
    return '<header class="page-header"><div><p class="eyebrow">CALIBRATION · ORIGINAL CATCHMENTS</p><h1>'+esc(map.title||'Catchment residual maps')+
      '</h1><p>Retained observed, native and adjusted annual loads on the original catchment geometry.</p></div><div class="page-actions">'+
      button('nominal','Nominal calibration',map.calibration_id)+(map.uncertainty_id?button('uncertainty','Source-error sensitivity',map.uncertainty_id):'')+
      button('prepare','New map selection',map.calibration_id,map.uncertainty_id?'data-uncertainty="'+esc(map.uncertainty_id)+'"':'')+
      button('gis','Build editable GIS project',map.id)+button('open','Refresh retained maps',map.id)+'</div></header>'+
      section('Original catchment layers','Choose an atlas to inspect its retained support, original source attributes and files.',
      '<div class="calibration-table-controls"><label><span>Find a layer</span><input type="search" id="calibration-map-search" value="'+esc(filter)+'" placeholder="Candidate, pollutant or units"></label></div>'+
      '<div id="calibration-map-layer-table">'+layerTable()+'</div>')+
      (value?layerDetails(value):'<p class="calibration-empty">This retained map edition has no map layers.</p>')+
      section('Editable GIS and complete source files',
        'Build the retained ordinary GIS project from this exact source selection. Its task retains the editable ZIP, QGIS project and offline viewer.',
        '<div class="section-body"><div class="page-actions">'+button('gis','Build editable GIS project',map.id)+'<button type="button" data-view="gis-projects">Open editable GIS projects</button></div></div>'+
        retainedFiles(packet._downloads??[])+
        '<ul class="calibration-notes">'+notes.map(note=>'<li>'+esc(typeof note==='string'?note:json(note))+'</li>').join('')+'</ul>'+
        '<details class="technical"><summary>Original calibration, catchment lineage and GIS selection</summary><pre class="json-view">'+
        esc(json({id:map.id,calibration_id:map.calibration_id,plan_id:map.plan_id,uncertainty_id:map.uncertainty_id,
          selection:map.selection,original_catchments:map.original_catchments,gis_selection:map.gis_selection}))+'</pre></details>');
  }
  function bind(root){
    if(!active())return;
    const input=root.querySelector('#calibration-map-search');
    input?.addEventListener('input',()=>{filter=input.value;root.querySelector('#calibration-map-layer-table').innerHTML=layerTable();});
  }
  async function dispatch(node){
    const action=node.dataset.action?.replace(/^calibration-maps-/,''),id=node.dataset.id;
    if(action==='preview')return preview(node.dataset.fileId);
    if(action==='prepare')return prepareForm(id,node.dataset.uncertainty||null);
    if(action==='open')return open(id);
    if(action==='layer'){layer(id);selectedLayer=id;return repaint();}
    if(action==='review'){
      const selected=layer(id);
      return submitAction('calibration.maps.review',{map_id:packet.map.id,layer_id:selected.id});
    }
    if(action==='gis'){
      if(!active()||packet.map.id!==id)throw Error('Open the original retained map edition before building its GIS project.');
      return submitAction('gis.project.export',JSON.parse(JSON.stringify(packet.map.gis_selection)));
    }
    if(action==='nominal'){reset();return openReport(id);}
    if(action==='uncertainty'){reset();return openUncertainty(id);}
  }
  return {active,reset,invalidate,sync,summary,open,render,bind,dispatch};
}

