  }
  function update(state=host.getState()) {
    if(!root)return;
    if(activeKey!==state?.workspace_key){detach();return;}
    const m=memory(),data=state.data?.parcel_source_desk;
    if(data && m.catalog)m.catalog={...m.catalog,...data};
